"""Builds QRINGS_REPORT.md from results2.json (and meta.json). python tools/qrings/make_report.py results2.json [before.json]"""
import json, sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from analyze import verdict
HERE = os.path.dirname(os.path.abspath(__file__))
STEP = {'gandrick': '3', 'ironhill': '5', 'mines': '6', 'overseer': '6 (side)', 'escape': '7', 'pass': '8', 'scoria': '9', 'kh_seal': '10', 'yar2': '14', 'kh_sea': '15', 'yar3': '16', 'yar4': '17', 'yar5': '18', 'yar6': '19', 'yar7': '20',
        'vq1': '21', 'vq2': '22', 'vq3': '23', 'vq4': '24', 'vq5': '25', 'kg0': '26', 'kg1': '27', 'kg2': '28', 'kg3': '29', 'kg4': '30', 'sd2': '31', 'vq6': '32', 'oq0': '33', 'oa1': '35', 'oa2': '36', 'oa3': '36', 'oa4': '36', 'oa6': '36', 'oa7': '36',
        'oa5': '37', 'oa8': '38', 'oa9': '39', 'ad1': '40', 'ad2': '41', 'ad3': '42', 'ad4': '43', 'hc1': '44', 'hc2': '45', 'hgb1': '49', 'hgb2': '50', 'hgb3': '51', 'hgb4': '52', 'hgrescue': '53', 'dh1': '54', 'dh2': '55', 'dh3': '56',
        'dq11': '58', 'dq12': '59', 'hgsph': '60', 'bsw1': '62', 'wk1': '65', 'wk2': '67', 'wk3': '68', 'mq1': 'monastery', 'mq2': 'monastery', 'shell': 'branch'}
for i in range(1, 9): STEP['sg%d' % i] = '34'
for i in range(1, 8): STEP['kh_c%d' % i] = '9 (Khemetra maps)'
for i in range(1, 6): STEP['gyq%d' % i] = 'Graveyard %d (L84-87)' % i
for i in range(1, 10): STEP['wwq%d' % i] = 'Witch %d' % i
res = json.load(open(sys.argv[1]))['res']
meta = json.load(open(HERE + '/meta.json')) if os.path.exists(HERE + '/meta.json') else {}
yn = lambda b: 'yes' if b else 'NO'
by = {}
for r in res: by.setdefault(r['id'], {})[r['stage']] = r
rows, fails = [], []
for id, st in by.items():
    m = meta.get(id) or {}
    v = {k: verdict(r) for k, r in st.items()}
    lv = lambda k: ', '.join(sorted({(x['name'] or str(x['lvl'])) + ' (%d)' % x['lvl'] for x in (m.get(k) or [])})[:3]) if m else ''
    notes = []
    for k in ('give', 'act', 'ready'):
        for n in v[k]['notes'][:2]: notes.append('%s: %s' % (k, n))
        if not (v[k]['ring'] and v[k]['place'] and v[k]['world']): fails.append((id, k, v[k]['notes']))
    place = all(v[k]['place'] for k in v); world = all(v[k]['world'] for k in v)
    rows.append('| %s | %s: %s | %s | %s | %s | %s | %s | %s | %s |' % (STEP.get(id, '?'), id, m.get('title', ''), lv('act'), m.get('giver') or m.get('who', ''),
                yn(v['give']['ring']), yn(v['act']['ring']), yn(place), yn(world), '; '.join(notes)[:200] or 'ok'))
out = ['# Quest rings report', '', 'Generated by tools/qrings/make_report.py from the harness run (tools/qrings/run2.py). One row per quest of the main line (and the graveyard, witch, monastery and shell chains).',
       'Each quest was set to each stage in turn (not taken, active, ready to hand in), clicked in the quest panel (the real handler `qrow_<id>`; untaken quests go through `questShow`, since the panel lists only taken quests) and the local map was read for the focus ring.', '',
       '| Step | Quest | Level of the work | Giver | Ring when not taken | Ring while active | Correct place | World map ring (other levels) | Notes |', '|---|---|---|---|---|---|---|---|---|'] + rows
out += ['', '## Summary', '', 'Quests checked: %d. Stage checks with a failure: %d of %d.' % (len(by), len(fails), len(res)), '']
for id, k, n in fails: out.append('- %s (%s): %s' % (id, k, '; '.join(n[:2])))
before = None
if len(sys.argv) > 2 and os.path.exists(sys.argv[2]):
    bres = json.load(open(sys.argv[2]))['res']; loc = noworld = nogo = 0; ids_bad = set(); cause = {}
    for r in bres:
        v = verdict(r); off = r.get('off') or {}
        lf = not (v['ring'] and v['place']); wf = not (off.get('ring') or off.get('wring')); gf = (not wf) and not off.get('goto') and not (off.get('ring') and off.get('door'))
        loc += lf; noworld += wf; nogo += gf
        if lf or wf or gf: ids_bad.add(r['id'])
        if lf:
            n = (v['notes'] or ['?'])[0]
            k = 'no ring on the local map (map or quest not wired)' if 'no ring' in n else 'ring on the giver, not on the place of the work' if 'not on target' in n else 'target not found' if 'not found' in n else 'other'
            cause[k] = cause.get(k, 0) + 1
    before = (loc, noworld, nogo, len(bres), cause, ids_bad)
if before:
    out += ['', '## Before the fix (the game as it was, quest_rings_fix.js switched off)', '', 'Of %d stage checks (quest x stage): %d had no ring on the right square of the local map, %d had no ring on the world map or a door when the party was elsewhere, and %d showed a ring but no "Go to ..." text. %d quests had at least one of these.' % (before[3], before[0], before[1], before[2], len(before[5])), '', 'Main causes of the local failures:', '']
    for k, n in sorted(before[4].items(), key=lambda x: -x[1]): out.append('- %s: %d' % (k, n))
    out += ['- Several levels had no way to place the quest at all (the Hollow Grasslands, Exsce, the Deeper Hollow, the Wenlock and graveyard levels, the monastery, the sea islands): the quest log only knew the giver, and on many of these levels the giver was not ringed either.', '- Kill, fetch and find quests ringed the giver, never the creatures or things to find.']
out += ['', '## How the rings work, and how a new quest gets one (notes for future agents)', '',
 '- The game already draws a ring for the quest picked in the Quests page (key J, row id `qrow_<id>`, handler `questShow`) through `questSpots()` and `drawQuestRings()` (index.html), which `mpplDraw` (maps_play.js) and the Khemetra map call on every area map. On another level `questShow` opens the world map (`G.qFocus.loc`, ring drawn in drawWorldMap) or, when a chain of doors leads there, rings the door on the local map.',
 '- The game only knew a giver or, for a few quests, a `QUESTS.<id>.spot()`. `src/desert/quest_rings_fix.js` (last in tools/inject.py ORDER) adds a table `QRF.T.<questId> = {give:[spec], act:[spec], ready:[spec]}` and wraps `questSpots`, `questTargetLevel`, `questWorldLoc`, `questShow` and `drawWorldMap`. `ready` defaults to `give`, `give` defaults to `act`.',
 '- A spec is `N(level,"npcId",...)` (people and things by decor id), `E(level,/type/)` (every live creature of that type), `I(level,"itemId")` (things on the ground), `K(level,"kind")`, `X(level,x,y)`, `CH(level,"X")` (exit squares) or `F(level,fn)` (a function returning [{x,y}]). Add `via:{<level>:[x,y]}` when the way in is not a normal door. `act` may be a function when the target changes with the quest step (see the graveyard quests).',
 '- To give a new quest a ring: add one line to QRF.T, run `python tools/inject.py`, add the id to tools/qrings/main_ids.json, run `python tools/qrings/run2.py tools/qrings/results_after.json <id>` and `python tools/qrings/analyze.py tools/qrings/results_after.json`. If the target only exists after a story event, put a JS snippet that sets the state in tools/qrings/flags.json.',
 '- The panel only lists quests the party has taken, so the "not taken" stage is checked through `questShow` directly (the same function the panel calls). Done quests show no ring and a note "is done".',
 '- Harness files: qlib.py (browser), qr_page.js (injected helpers and canvas hooks), run2.py (all stages), doors.py (walk the doors step by step), lifecycle.py (ring goes when done or when the map is left), shots.py (screenshots), analyze.py, make_report.py, meta.py, dump_data.py (levels, people, doors to JSON).',
 '- Known: the Exsce map (level 481, hgt_town_exsce.js `exmDraw`) throws when opened (EXTINT has no entry for some wall type) and froze the game; quest_rings_fix.js now catches a throwing level map and draws a plain map of the level with the rings and a Close button, and a separate task was opened to fix `exmDraw` itself. In the Khemetra sea tunnel (level 266) the ring target is reached through a teleporter.']
open(HERE + '/QRINGS_REPORT.md', 'w', encoding='utf-8').write('\n'.join(out) + '\n')
print('failures', len(fails), 'of', len(res))
